// #3203 (Phase 2 of #805): checkMigrationDrift (worker/index.js) and the
// content-hash lock (Phase 1) cover "a migration file is missing from
// production" and "an applied migration was edited in the repo". Neither can
// see an out-of-band change to the *live* database -- a manual hotfix
// `ALTER TABLE` / `CREATE INDEX` that bypassed the migrations system -- because
// neither looks at the live schema. This does: once a day it reads production's
// schema and compares it with worker/schema-snapshot.json, a normalized
// snapshot of what a fresh apply of migrations/ produces (generated by
// scripts/generate-schema-snapshot.mjs and kept fresh by a pretest check, the
// same way worker/migrations-manifest.json is).
//
// The comparison is structural where SQLite allows it, to avoid false
// positives: tables are compared as sets of columns (name, declared type,
// NOT NULL, default, primary-key position -- column order is not significant),
// and indexes/triggers/views by name plus their whitespace-collapsed SQL.
// SQLite-internal tables (sqlite_*), Cloudflare's (_cf_*) and the migrations
// bookkeeping table (d1_*) are excluded.
//
// Same alerting shape as checkWebhookSecrets: console.error on every run,
// one self-clearing Control Room card, and (only when OPS_ALERT_EMAIL is
// configured, and only when the card is raised or re-raised, never on every
// run) an email.
const excludedNames = (column) => `${column} NOT LIKE 'sqlite\\_%' ESCAPE '\\' AND ${column} NOT LIKE '\\_cf\\_%' ESCAPE '\\' AND ${column} NOT LIKE 'd1\\_%' ESCAPE '\\'`;

// Both queries are shared, verbatim, by the Worker (D1) and the snapshot
// generator (node:sqlite), so the two sides cannot disagree about what is read.
export const SCHEMA_COLUMNS_SQL = `
  SELECT m.name AS tbl, p.name AS col, p.type AS type, p."notnull" AS not_null, p.dflt_value AS dflt, p.pk AS pk
  FROM sqlite_master m, pragma_table_info(m.name) p
  WHERE m.type = 'table' AND ${excludedNames('m.name')}
  ORDER BY m.name, p.cid
`;
export const SCHEMA_OBJECTS_SQL = `
  SELECT type, name, tbl_name AS tbl, sql
  FROM sqlite_master
  WHERE type IN ('index', 'trigger', 'view') AND sql IS NOT NULL AND ${excludedNames('name')}
  ORDER BY type, name
`;

export function normalizeSql(sql) {
  return String(sql ?? '').replace(/\s+/g, ' ').trim();
}

// rows from SCHEMA_COLUMNS_SQL / SCHEMA_OBJECTS_SQL -> a plain, sorted,
// JSON-stable snapshot: { tables: { tbl: { col: "TYPE|notnull|default|pk" } },
// objects: { "index:name": { tbl, sql } } }.
export function buildSchemaSnapshot(columnRows, objectRows) {
  const tables = {};
  for (const row of columnRows) {
    tables[row.tbl] ??= {};
    tables[row.tbl][row.col] = [
      String(row.type ?? '').toUpperCase(),
      row.not_null ? 1 : 0,
      row.dflt === null || row.dflt === undefined ? '' : String(row.dflt),
      row.pk ?? 0,
    ].join('|');
  }
  const objects = {};
  for (const row of objectRows) {
    objects[`${row.type}:${row.name}`] = { tbl: row.tbl, sql: normalizeSql(row.sql) };
  }
  const sortKeys = (value) => Object.fromEntries(Object.entries(value).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
  return {
    tables: sortKeys(Object.fromEntries(Object.entries(tables).map(([name, columns]) => [name, sortKeys(columns)]))),
    objects: sortKeys(objects),
  };
}

// Human-readable differences, expected (migrations/) vs actual (live), in a
// stable order. Empty array = no drift.
export function diffSchemaSnapshots(expected, actual) {
  const differences = [];
  const tableNames = [...new Set([...Object.keys(expected.tables), ...Object.keys(actual.tables)])].sort();
  for (const table of tableNames) {
    const want = expected.tables[table];
    const have = actual.tables[table];
    if (!want) {
      differences.push(`table ${table} exists in production but not in migrations/`);
      continue;
    }
    if (!have) {
      differences.push(`table ${table} is in migrations/ but missing in production`);
      continue;
    }
    for (const column of [...new Set([...Object.keys(want), ...Object.keys(have)])].sort()) {
      if (!(column in have)) differences.push(`column ${table}.${column} is missing in production`);
      else if (!(column in want)) differences.push(`column ${table}.${column} exists in production but not in migrations/`);
      else if (want[column] !== have[column]) {
        differences.push(`column ${table}.${column} differs (migrations/ ${want[column]} vs production ${have[column]}; type|notnull|default|pk)`);
      }
    }
  }
  const objectNames = [...new Set([...Object.keys(expected.objects), ...Object.keys(actual.objects)])].sort();
  for (const key of objectNames) {
    const want = expected.objects[key];
    const have = actual.objects[key];
    if (!want) differences.push(`${key.replace(':', ' ')} exists in production but not in migrations/`);
    else if (!have) differences.push(`${key.replace(':', ' ')} is in migrations/ but missing in production`);
    else if (want.tbl !== have.tbl || want.sql !== have.sql) differences.push(`${key.replace(':', ' ')} differs from migrations/`);
  }
  return differences;
}

export async function readLiveSchemaSnapshot(db) {
  const [columns, objects] = await Promise.all([
    db.prepare(SCHEMA_COLUMNS_SQL).all(),
    db.prepare(SCHEMA_OBJECTS_SQL).all(),
  ]);
  return buildSchemaSnapshot(columns.results, objects.results);
}

export const SCHEMA_DRIFT_CARD_ID = 'ops-schema-drift';
const MAX_LISTED_DIFFERENCES = 25;

// `expected` (worker/schema-snapshot.json) and `sendEmail` are passed in by
// worker/index.js, which already owns the JSON import and sendEmail: this
// module stays free of both so the Node-side snapshot scripts can import it
// without a JSON loader, and to avoid a circular import.
export async function checkSchemaDrift(env, { expected, sendEmail } = {}) {
  if (!env.DB || !expected) return [];
  let actual;
  try {
    actual = await readLiveSchemaSnapshot(env.DB);
  } catch (error) {
    console.error('checkSchemaDrift: failed to read the live schema', error);
    return [];
  }
  const differences = diffSchemaSnapshots(expected, actual);
  const now = new Date().toISOString();

  if (differences.length === 0) {
    // Self-clearing, like checkWebhookSecrets: once production matches migrations/
    // again, the card resolves itself.
    await env.DB.prepare(
      `UPDATE control_room_tasks SET status = 'done', waiting_on = NULL, note = ?, note_updated_at = ?, note_author = 'system', updated_at = ?
       WHERE task_id = ? AND status != 'done'`,
    ).bind('Production D1 matches the schema migrations/ produces again.', now, now, SCHEMA_DRIFT_CARD_ID).run();
    return [];
  }

  const listed = differences.slice(0, MAX_LISTED_DIFFERENCES);
  const more = differences.length > listed.length ? ` (and ${differences.length - listed.length} more)` : '';
  const summary = `${listed.join('; ')}${more}`;
  console.error(`SCHEMA DRIFT DETECTED: production D1 differs from what migrations/ produces: ${summary}`);

  const title = '[owner action needed] Production D1 schema differs from migrations/ (an out-of-band change)';
  const note = `Production's live schema no longer matches a fresh apply of migrations/: ${summary}. This usually means a manual ALTER/CREATE/DROP was run against production outside the migrations system. Either revert it, or capture it in a new migration (and regenerate worker/schema-snapshot.json with npm run generate:schema-snapshot). This card resolves itself once production matches again.`;
  const inserted = await env.DB.prepare(
    `INSERT OR IGNORE INTO control_room_tasks
       (task_id, kind, note_number, title, status, session, posted_by, waiting_on, note, note_updated_at, note_author, created_at, updated_at)
     VALUES (?, 'feedback', (SELECT COALESCE(MAX(note_number), 0) + 1 FROM control_room_tasks), ?, 'queued', '', 'system', 'owner', ?, ?, 'system', ?, ?)`,
  ).bind(SCHEMA_DRIFT_CARD_ID, title, note, now, now, now).run();
  // The card stays after it resolves, so a later episode re-opens it (and
  // only a newly raised / re-opened card sends the optional email).
  const reopened = await env.DB.prepare(
    `UPDATE control_room_tasks SET status = 'queued', waiting_on = 'owner', title = ?, note = ?, note_updated_at = ?, note_author = 'system', updated_at = ?
     WHERE task_id = ? AND status = 'done'`,
  ).bind(title, note, now, now, SCHEMA_DRIFT_CARD_ID).run();
  const newlyRaised = inserted.meta.changes > 0 || reopened.meta.changes > 0;

  if (newlyRaised && env.OPS_ALERT_EMAIL && sendEmail) {
    await sendEmail(env, {
      to: env.OPS_ALERT_EMAIL,
      subject: 'higglehaven: production D1 schema differs from migrations/',
      text: note,
      html: `<p>${note}</p>`,
    });
  }
  return differences;
}
